/// `<struct name="Tiler Heap">`, 32 bytes.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct TilerHeap {
    /// `Type`: bits 0..=3.
    pub type_: DescriptorType,
    /// `Buffer type`: bits 4..=7.
    pub buffer_type: BufferType,
    /// `Size`: bits 32..=63, align(4096).
    pub size: u32,
    /// `Base`: bits 64..=127.
    pub base: u64,
    /// `Bottom`: bits 128..=191.
    pub bottom: u64,
    /// `Top`: bits 192..=255.
    pub top: u64,
}

impl Default for TilerHeap {
    fn default() -> Self {
        Self {
            type_: DescriptorType::BUFFER,
            buffer_type: BufferType::TILER_HEAP,
            size: Default::default(),
            base: Default::default(),
            bottom: Default::default(),
            top: Default::default(),
        }
    }
}

impl TilerHeap {
    /// The name v10.xml gives this struct.
    pub const XML_NAME: &'static str = "Tiler Heap";
    /// Bytes, as Mesa's `MALI_TILER_HEAP_LENGTH`.
    pub const LENGTH: usize = 32;
    /// Alignment in bytes, as Mesa's `MALI_TILER_HEAP_ALIGN`.
    pub const ALIGN: usize = 32;

    /// The descriptor's bytes, or the first field that does not fit.
    pub fn pack(&self) -> Result<[u8; 32], PackError> {
        let mut p = Packer::<8, 6>::new(Self::XML_NAME);
        p.enum_value("Type", 0, 4, self.type_.0, self.type_.is_known(), &DescriptorType::DEF)?;
        p.enum_value("Buffer type", 4, 4, self.buffer_type.0, self.buffer_type.is_known(), &BufferType::DEF)?;
        p.uint_align("Size", 32, 32, u64::from(self.size), 4096)?;
        p.uint("Base", 64, 64, self.base)?;
        p.uint("Bottom", 128, 64, self.bottom)?;
        p.uint("Top", 192, 64, self.top)?;
        p.finish()
    }

    /// The fields of a packed descriptor; refuses a set bit no field owns.
    pub fn unpack(bytes: &[u8; 32]) -> Result<Self, PackError> {
        const OWNED: [u32; 8] = [0xff, 0xffff_ffff, 0xffff_ffff, 0xffff_ffff, 0xffff_ffff, 0xffff_ffff, 0xffff_ffff, 0xffff_ffff];
        let u = Unpacker::<8>::new(Self::XML_NAME, bytes, &OWNED)?;
        Ok(TilerHeap {
            type_: DescriptorType(u.enum_value("Type", 0, 4, |v| DescriptorType(v).is_known(), DescriptorType::XML_NAME)?),
            buffer_type: BufferType(u.enum_value("Buffer type", 4, 4, |v| BufferType(v).is_known(), BufferType::XML_NAME)?),
            size: u.narrow("Size", u.uint_align("Size", 32, 32, 4096)?)?,
            base: u.uint(64, 64),
            bottom: u.uint(128, 64),
            top: u.uint(192, 64),
        })
    }
}

